package com.company.platform.analytics.infrastructure;
import java.util.*;import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.StringDeserializer;import org.springframework.context.annotation.*;import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;import org.springframework.kafka.core.*;import org.springframework.kafka.support.serializer.JsonDeserializer;import org.springframework.kafka.listener.*;import org.springframework.util.backoff.FixedBackOff;
@Configuration public class KafkaConfiguration{@Bean ConsumerFactory<String,com.fasterxml.jackson.databind.JsonNode> analyticsConsumerFactory(){Map<String,Object> p=new HashMap<>();p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG,System.getenv().getOrDefault("KAFKA_BOOTSTRAP_SERVERS","localhost:9092"));p.put(ConsumerConfig.GROUP_ID_CONFIG,"analytics-service");p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG,StringDeserializer.class);p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,JsonDeserializer.class);p.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG,false);p.put(JsonDeserializer.TRUSTED_PACKAGES,"*");return new DefaultKafkaConsumerFactory<>(p,new StringDeserializer(),new JsonDeserializer<>(com.fasterxml.jackson.databind.JsonNode.class,false));}@Bean ConcurrentKafkaListenerContainerFactory<String,com.fasterxml.jackson.databind.JsonNode> analyticsKafkaListenerContainerFactory(ConsumerFactory<String,com.fasterxml.jackson.databind.JsonNode> f,ProducerFactory<Object,Object> producer){var x=new ConcurrentKafkaListenerContainerFactory<String,com.fasterxml.jackson.databind.JsonNode>();x.setConsumerFactory(f);var template=new KafkaTemplate<>(producer);x.setCommonErrorHandler(new DefaultErrorHandler(new DeadLetterPublishingRecoverer(template),new FixedBackOff(1000L,2L)));return x;}@Bean ProducerFactory<Object,Object> analyticsProducerFactory(){Map<String,Object> p=new HashMap<>();p.put(org.apache.kafka.clients.producer.ProducerConfig.BOOTSTRAP_SERVERS_CONFIG,System.getenv().getOrDefault("KAFKA_BOOTSTRAP_SERVERS","localhost:9092"));p.put(org.apache.kafka.clients.producer.ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG,org.apache.kafka.common.serialization.StringSerializer.class);p.put(org.apache.kafka.clients.producer.ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,org.springframework.kafka.support.serializer.JsonSerializer.class);return new DefaultKafkaProducerFactory<>(p);}}
